def sort_students(records):
    if not records:
        return [], {"tied_grades": 0}
    counts = {}
    for r in records:
        g = r["grade"]
        counts[g] = counts.get(g, 0) + 1
    tied = sum(1 for v in counts.values() if v >= 2)
    ordered = sorted(records, key=lambda x: x["grade"], reverse=True)
    return ordered, {"tied_grades": tied}
